-- Pre-Registration local-dev-setup init (single init.sql, same layout as id-repository).
-- Creates mosip_prereg, mosip_keymgr, and mosip_audit, applies DDL via \i, and inlines the keymgr seed.
-- Each is its own database. They are not merged into each other or into mosip_kernel (PRID).

CREATE ROLE prereguser WITH LOGIN PASSWORD 'mosip123';
CREATE ROLE keymgruser WITH LOGIN PASSWORD 'mosip123';
CREATE ROLE audituser WITH LOGIN PASSWORD 'mosip123';

CREATE DATABASE mosip_prereg
	ENCODING = 'UTF8'
	TABLESPACE = pg_default
	OWNER = postgres
	TEMPLATE  = template0;
COMMENT ON DATABASE mosip_prereg IS 'Pre-registration database to store the data that is captured as part of pre-registration process';

-- ===================== mosip_prereg =====================
\c mosip_prereg

\set mosipdbname mosip_prereg
\set dbuname prereguser

CREATE SCHEMA prereg;
ALTER SCHEMA prereg OWNER TO postgres;
ALTER DATABASE mosip_prereg SET search_path TO prereg,pg_catalog,public;
SET search_path TO prereg,pg_catalog,public;
GRANT CONNECT ON DATABASE mosip_prereg TO prereguser;
GRANT USAGE ON SCHEMA prereg TO prereguser;
ALTER DEFAULT PRIVILEGES IN SCHEMA prereg GRANT SELECT,INSERT,UPDATE,DELETE,REFERENCES ON TABLES TO prereguser;

\i /db_scripts/mosip_prereg/ddl/applicant_demographic.sql
\i /db_scripts/mosip_prereg/ddl/applicant_demographic_consumed.sql
\i /db_scripts/mosip_prereg/ddl/applicant_document.sql
\i /db_scripts/mosip_prereg/ddl/applicant_document_consumed.sql
\i /db_scripts/mosip_prereg/ddl/batch_job_instance.sql
\i /db_scripts/mosip_prereg/ddl/batch_job_execution.sql
\i /db_scripts/mosip_prereg/ddl/batch_job_execution_context.sql
\i /db_scripts/mosip_prereg/ddl/batch_job_execution_param.sql
\i /db_scripts/mosip_prereg/ddl/batch_step_execution.sql
\i /db_scripts/mosip_prereg/ddl/batch_step_execution_context.sql
\i /db_scripts/mosip_prereg/ddl/intf_processed_prereg_list.sql
\i /db_scripts/mosip_prereg/ddl/processed_prereg_list.sql
\i /db_scripts/mosip_prereg/ddl/reg_appointment.sql
\i /db_scripts/mosip_prereg/ddl/reg_appointment_consumed.sql
\i /db_scripts/mosip_prereg/ddl/reg_available_slot.sql
\i /db_scripts/mosip_prereg/ddl/otp_transaction.sql
\i /db_scripts/mosip_prereg/ddl/applications.sql
\i /db_scripts/mosip_prereg/ddl/user_details.sql
\i /db_scripts/mosip_prereg/ddl/fk.sql
\i /db_scripts/mosip_prereg/ddl/batch-fk.sql
\i /db_scripts/mosip_prereg/ddl/anonymous_profile.sql

-- Local slots so getAvailability works without batchjob. Centre 10003 matches api-test.
INSERT INTO prereg.reg_available_slot (
	regcntr_id, availability_date, slot_from_time, slot_to_time,
	available_kiosks, cr_by, cr_dtimes, is_deleted)
SELECT
	'10003',
	d::date,
	t.from_t,
	t.to_t,
	4,
	'local-dev',
	now(),
	false
FROM generate_series(CURRENT_DATE + 2, CURRENT_DATE + 16, interval '1 day') AS d
CROSS JOIN (
	VALUES
		(time '09:00:00', time '09:15:00'),
		(time '09:15:00', time '09:30:00'),
		(time '09:30:00', time '09:45:00')
) AS t(from_t, to_t);

GRANT SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES ON ALL TABLES IN SCHEMA prereg TO prereguser;

-- ===================== mosip_audit =====================
-- Schema from https://github.com/mosip/audit-manager/tree/issue-1633/db_scripts
CREATE DATABASE mosip_audit
	ENCODING = 'UTF8'
	TABLESPACE = pg_default
	OWNER = postgres
	TEMPLATE  = template0;
COMMENT ON DATABASE mosip_audit IS 'Audit related logs and the data is stored in this database';

\c mosip_audit

CREATE SCHEMA audit;
ALTER SCHEMA audit OWNER TO postgres;
ALTER DATABASE mosip_audit SET search_path TO audit,pg_catalog,public;
SET search_path TO audit,pg_catalog,public;
GRANT CONNECT ON DATABASE mosip_audit TO audituser;
GRANT USAGE ON SCHEMA audit TO audituser;
ALTER DEFAULT PRIVILEGES IN SCHEMA audit GRANT SELECT,INSERT,UPDATE,DELETE,REFERENCES ON TABLES TO audituser;

\i /audit/ddl/audit-app_audit_log.sql

GRANT SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES ON ALL TABLES IN SCHEMA audit TO audituser;

-- ===================== mosip_keymgr =====================
-- Static seed below is paired with keys/mosip-prereg-ks.p12 (password 1234). Do not regenerate that PKCS12.
-- PRE_REGISTRATION/INDIVIDUAL is not in the seed. Bootstrap getCertificate creates that keypair.
CREATE DATABASE mosip_keymgr
	ENCODING = 'UTF8'
	TABLESPACE = pg_default
	OWNER = postgres
	TEMPLATE  = template0;
COMMENT ON DATABASE mosip_keymgr IS 'Key Manager database for encryption keys and certificates';

\c mosip_keymgr

CREATE SCHEMA keymgr;
ALTER SCHEMA keymgr OWNER TO postgres;
ALTER DATABASE mosip_keymgr SET search_path TO keymgr,pg_catalog,public;
SET search_path TO keymgr,pg_catalog,public;
GRANT CONNECT ON DATABASE mosip_keymgr TO keymgruser;
GRANT USAGE ON SCHEMA keymgr TO keymgruser;
ALTER DEFAULT PRIVILEGES IN SCHEMA keymgr GRANT SELECT,INSERT,UPDATE,DELETE,REFERENCES ON TABLES TO keymgruser;

\i /keymanager/ddl/keymgr-key_alias.sql
\i /keymanager/ddl/keymgr-key_policy_def.sql
\i /keymanager/ddl/keymgr-key_store.sql
\i /keymanager/ddl/keymgr-data_encrypt_keystore.sql
\i /keymanager/ddl/keymgr-ca_cert_store.sql
\i /keymanager/ddl/keymgr-partner_cert_store.sql
\i /keymanager/ddl/keymgr-licensekey_list.sql
\i /keymanager/ddl/keymgr-licensekey_permission.sql
\i /keymanager/ddl/keymgr-tsp_licensekey_map.sql
\i /keymanager/ddl/keymgr-fk.sql

GRANT SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES ON ALL TABLES IN SCHEMA keymgr TO keymgruser;

SET search_path TO keymgr,pg_catalog,public;

TRUNCATE TABLE keymgr.data_encrypt_keystore CASCADE;
TRUNCATE TABLE keymgr.key_store CASCADE;
TRUNCATE TABLE keymgr.key_alias CASCADE;
TRUNCATE TABLE keymgr.key_policy_def CASCADE;

